head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > ajax]<br/>AJAX 방식으로 HTTP 통신을 수행합니다.",
    "validation" : [
        "options 객체로 URL, 메소드, 데이터, 헤더, 콜백 등을 설정할 수 있습니다.",
        "options(필수) 파라미터로 AJAX 통신 옵션을 JSON 객체로 설정할 수 있어야 합니다.",
        "options.action(필수) 으로 AJAX 요청을 보낼 서버 URL 을 설정할 수 있어야 합니다.",
        "options.requestHeader 로 커스텀 헤더 정보를 설정할 수 있어야 합니다.",
        "options.success 는 HTTP 200-299 응답 시 호출되며 responseStatusCode / responseText / responseJSON 등 응답 객체를 전달받아야 합니다.",
        "options.error 는 요청 실패 또는 타임아웃 시 호출되며 errorType('resource-error'/'timeout-error') 을 포함한 오류 객체를 전달받아야 합니다.",
        "options.beforeAjax 가 false 를 반환하면 AJAX 요청이 취소되어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// requestHeader 수집용 플래그
scwin.collectedHeaders = [];
scwin.originalSetRequestHeader = null;

// XMLHttpRequest.setRequestHeader 패치로 실제 설정된 헤더 수집
scwin.patchSetRequestHeader = function () {
    if (scwin.originalSetRequestHeader === null) {
        scwin.originalSetRequestHeader = XMLHttpRequest.prototype.setRequestHeader;
    }
    scwin.collectedHeaders = [];
    XMLHttpRequest.prototype.setRequestHeader = function (name, value) {
        scwin.collectedHeaders.push({name: name, value: value});
        return scwin.originalSetRequestHeader.apply(this, arguments);
    };
};

scwin.restoreSetRequestHeader = function () {
    if (scwin.originalSetRequestHeader !== null) {
        XMLHttpRequest.prototype.setRequestHeader = scwin.originalSetRequestHeader;
    }
};



scwin.btn_ajax_onclick = function () {
    var scenario = par_scenario.getValue();

    // 매 시나리오 실행 시 이전 gridView 데이터 초기화
    dlt_userList.removeAll();

    if (scenario === "1") {
        // 시나리오 1 : 기본 성공 - success 콜백 + 응답 데이터를 dlt_userList 에 수동 바인딩 → gridView 표시
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : 기본 성공 (success 콜백) ──");
        $p.ajax({
            "action" : "/data/$p_createSubmission_userList.json",
            "method" : "post",
            "mediatype" : "application/json",
            "requestData" : {"key" : "value"},
            "processMsg" : "",
            "success" : function (e) {
                var hasJSON = (e.responseJSON !== undefined && e.responseJSON !== null);
                var list = hasJSON ? (e.responseJSON.dlt_userList || []) : [];

                // 응답 데이터를 dlt_userList 에 수동 바인딩 → gridView 자동 갱신
                for (var i = 0; i < list.length; i++) {
                    var rowIdx = dlt_userList.insertRow(i);
                    dlt_userList.setCellData(rowIdx, "id", list[i].id);
                    dlt_userList.setCellData(rowIdx, "name", list[i].name);
                    dlt_userList.setCellData(rowIdx, "age", list[i].age);
                    dlt_userList.setCellData(rowIdx, "dept", list[i].dept);
                }

                wf_body_bottom.getObj("scwin").setReturnValue("responseStatusCode=" + e.responseStatusCode);
                wf_body_bottom.getObj("scwin").setReturnValue("responseJSON 존재: " + hasJSON);
                wf_body_bottom.getObj("scwin").setReturnValue("dlt_userList 바인딩 건수: " + dlt_userList.getRowCount());
            },
            "error" : function (e) {
                wf_body_bottom.getObj("scwin").setReturnValue("error 호출됨: errorType=" + e.errorType);
            }
        });
    } else if (scenario === "2") {
        // 시나리오 2 : requestHeader 추가
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : requestHeader 추가 ──");
        scwin.patchSetRequestHeader();
        $p.ajax({
            "action" : "/data/$p_createSubmission_userList.json",
            "method" : "post",
            "mediatype" : "application/json",
            "requestData" : {"key" : "value"},
            "requestHeader" : {
                "Authorization" : "Bearer token123",
                "X-Custom" : "test"
            },
            "processMsg" : "",
            "success" : function (e) {
                // 커스텀 헤더만 필터링 (Authorization, X-Custom)
                var filtered = [];
                for (var i = 0; i < scwin.collectedHeaders.length; i++) {
                    var h = scwin.collectedHeaders[i];
                    if (h.name === "Authorization" || h.name === "X-Custom") {
                        filtered.push(h.name + "=" + h.value);
                    }
                }
                wf_body_bottom.getObj("scwin").setReturnValue("설정된 requestHeader: " + filtered.join(", "));
                scwin.restoreSetRequestHeader();
            },
            "error" : function (e) {
                wf_body_bottom.getObj("scwin").setReturnValue("error 호출됨: errorType=" + e.errorType);
                scwin.restoreSetRequestHeader();
            }
        });
    } else if (scenario === "3") {
        // 시나리오 3 : error 콜백 - 404 resource-error
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : error 콜백 (404 resource-error) ──");
        $p.ajax({
            "action" : "/data/$p_ajax_not_exist.json",
            "method" : "post",
            "mediatype" : "application/json",
            "requestData" : {"key" : "value"},
            "processMsg" : "",
            "success" : function (e) {
                wf_body_bottom.getObj("scwin").setReturnValue("success 호출됨 (실패 예상이었으나 성공)");
            },
            "error" : function (e) {
                wf_body_bottom.getObj("scwin").setReturnValue("error 콜백 호출됨");
                wf_body_bottom.getObj("scwin").setReturnValue("errorType=" + e.errorType);
                wf_body_bottom.getObj("scwin").setReturnValue("responseStatusCode=" + e.responseStatusCode);
            }
        });
    } else if (scenario === "4") {
        // 시나리오 4 : beforeAjax false 반환 - 요청 취소
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 4 : beforeAjax false 반환 (요청 취소) ──");
        var successCalled = false;
        var errorCalled = false;
        $p.ajax({
            "action" : "/data/$p_createSubmission_userList.json",
            "method" : "post",
            "mediatype" : "application/json",
            "requestData" : {"key" : "value"},
            "processMsg" : "",
            "beforeAjax" : function (e) {
                return false;
            },
            "success" : function (e) {
                successCalled = true;
            },
            "error" : function (e) {
                errorCalled = true;
            }
        });

        // 500ms 대기 후 flag 로 검증
        $p.setTimeout(function () {
            wf_body_bottom.getObj("scwin").setReturnValue("beforeAjax false 반환 → 요청 취소됨");
            wf_body_bottom.getObj("scwin").setReturnValue("success 호출: " + successCalled + ", error 호출: " + errorCalled);
        }, "chk_beforeAjax", 500);
    } else if (scenario === "5") {
        // 시나리오 5 : timeout 발생 (timeout-error) - 미도달 URL + 짧은 timeout
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 5 : timeout 발생 (timeout-error) ──");
        $p.ajax({
            "action" : "http://10.255.255.1/ajax_timeout_test.json",
            "method" : "post",
            "mediatype" : "application/json",
            "requestData" : {"key" : "value"},
            "timeout" : 50,
            "processMsg" : "",
            "success" : function (e) {
                wf_body_bottom.getObj("scwin").setReturnValue("success 호출됨 (타임아웃 예상이었으나 성공)");
            },
            "error" : function (e) {
                wf_body_bottom.getObj("scwin").setReturnValue("error 콜백 호출됨");
                wf_body_bottom.getObj("scwin").setReturnValue("errorType=" + e.errorType + " (예상: 'timeout-error')");
                wf_body_bottom.getObj("scwin").setReturnValue("time=" + e.time + "ms");
            }
        });
    } else if (scenario === "6") {
        // 시나리오 6 : GET 방식 호출 + 응답 데이터 바인딩
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 6 : GET 방식 ──");

        $p.ajax({
            "action" : "/data/$p_createSubmission_userList.json",
            "method" : "get",
            "mediatype" : "application/json",
            "processMsg" : "",
            "success" : function (e) {
                // 응답 데이터를 dlt_userList 에 바인딩 → gridView 자동 갱신
                var hasJSON = (e.responseJSON !== undefined && e.responseJSON !== null);
                var list = hasJSON ? (e.responseJSON.dlt_userList || []) : [];
                for (var i = 0; i < list.length; i++) {
                    var rowIdx = dlt_userList.insertRow(i);
                    dlt_userList.setCellData(rowIdx, "id", list[i].id);
                    dlt_userList.setCellData(rowIdx, "name", list[i].name);
                    dlt_userList.setCellData(rowIdx, "age", list[i].age);
                    dlt_userList.setCellData(rowIdx, "dept", list[i].dept);
                }

                wf_body_bottom.getObj("scwin").setReturnValue("method=get / responseStatusCode=" + e.responseStatusCode);
                wf_body_bottom.getObj("scwin").setReturnValue("dlt_userList 바인딩 건수: " + dlt_userList.getRowCount());
            },
            "error" : function (e) {
                wf_body_bottom.getObj("scwin").setReturnValue("error 호출됨: errorType=" + e.errorType);
            }
        });
    }
};
